-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Introdução à Tecnologia da Informação e Comunicação' and a.numero = 5
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 5 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 05', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 05 (10 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-PRATICA-AULA-05.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique cada pilar da tríade CIA (confidencialidade, integridade e disponibilidade).', 0.5, 'Confidencialidade: só pessoas autorizadas acessam os dados (credenciais, criptografia). Integridade: os dados não são alterados indevidamente e continuam corretos (assinaturas, auditoria). Disponibilidade: os dados e sistemas estão acessíveis quando necessário (servidores redundantes, plano de recuperação).', 'Nota cheia: os três pilares corretos. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 1, 2, 'Indique qual pilar foi violado em cada um dos três incidentes, justificando.', 0.5, 'Vazamento da lista de clientes: confidencialidade (dados vistos por quem não devia). Vírus alterando notas fiscais: integridade (dados modificados). Portal fora do ar por sobrecarga (DDoS): disponibilidade (sistema inacessível).', 'Nota cheia: os três incidentes certos com justificativa. Metade: dois certos. Zero: um ou nenhum.'),
      (v_atividade, 2, 1, 'Classifique os dados da planilha em dados pessoais comuns e dados pessoais sensíveis.', 0.5, 'Comuns: nome completo, CPF, telefone, endereço. Sensíveis: religião (convicção religiosa), tipo sanguíneo (dado de saúde), digital biométrica (dado biométrico).', 'Nota cheia: os sete dados classificados corretamente. Metade: cinco ou seis. Zero: quatro ou menos.'),
      (v_atividade, 2, 2, 'Explique o que a LGPD exige sobre finalidade e guarda dos dados, quem fiscaliza e o problema da sugestão do colega.', 0.5, 'A LGPD (Lei 13.709/2018) exige finalidade legítima e explícita para cada dado, coletar só o necessário (religião e tipo sanguíneo provavelmente não têm finalidade aqui), guardar só pelo tempo necessário e proteger os dados. A fiscalização é da ANPD, com multas de até 2% do faturamento (limite de R$ 50 milhões por infração). Guardar para sempre e espalhar no grupo de mensagens viola a finalidade, a segurança e expõe dados sensíveis.', 'Nota cheia: finalidade + tempo de guarda/segurança + ANPD + crítica à sugestão. Metade: dois ou três desses pontos. Zero: um ou nenhum.'),
      (v_atividade, 3, 1, 'Explique qual lei trata desse caso, que crime ela criou e por que a atitude do conferente se encaixa nele.', 0.6, 'Lei Carolina Dieckmann (Lei 12.737/2012), que incluiu no Código Penal (art. 154-A) o crime de invasão de dispositivo informático. O conferente usou credenciais de outra pessoa, sem autorização, para acessar uma pasta restrita: violou mecanismo de segurança e acessou dados indevidamente.', 'Nota cheia: lei + crime + aplicação ao caso. Metade: lei e crime sem aplicar, ou aplicação sem a lei. Zero: lei errada.'),
      (v_atividade, 3, 2, 'Cite as possíveis consequências para o conferente no trabalho e na justiça.', 0.4, 'No trabalho: demissão por justa causa e perda da confiança. Na justiça: processo criminal com pena (reclusão/detenção e multa) e possível responsabilização civil pelos danos.', 'Nota cheia: consequências no trabalho e na justiça. Metade: só uma delas. Zero: diz que não há consequência.'),
      (v_atividade, 4, 1, 'Aponte pelo menos três sinais de que a mensagem é phishing e explique que técnica de engenharia social ela usa.', 0.6, 'Sinais: remetente falso/parecido ("va1esul" com número 1 no lugar do l); link para domínio diferente do oficial ("valesul-login-seguro.com"); urgência e ameaça ("bloqueada em 2 horas"); pedido de usuário e senha por e-mail. Técnica: engenharia social, explorando medo e urgência para induzir o clique.', 'Nota cheia: três sinais + engenharia social (medo/urgência). Metade: dois sinais ou três sinais sem a técnica. Zero: um ou nenhum.'),
      (v_atividade, 4, 2, 'Descreva o que você deve fazer (e não fazer) com esse e-mail.', 0.4, 'Não clicar no link, não responder, não abrir anexos nem digitar a senha. Reportar ao suporte de TI (encaminhar como suspeito/phishing) e apagar. Se já clicou ou digitou a senha, trocar a senha imediatamente e avisar a TI.', 'Nota cheia: o que não fazer + reportar à TI. Metade: só um dos dois. Zero: sugere clicar para conferir.'),
      (v_atividade, 5, 1, 'Indique o tipo de malware de cada um dos quatro casos (vírus, worm, trojan ou spyware/keylogger), justificando.', 0.6, 'Espalhou-se sozinho pela rede: worm. "Gerador de etiquetas grátis" que abriu acesso remoto: trojan (cavalo de Troia, backdoor). Gravava o que era digitado: spyware/keylogger. "romaneio.pdf.exe" aberto pelo usuário: vírus (precisa de arquivo hospedeiro e da ação do usuário; extensão dupla).', 'Nota cheia: os quatro certos com justificativa. Metade: dois ou três certos. Zero: um ou nenhum.'),
      (v_atividade, 5, 2, 'Explique a diferença entre um vírus e um worm na forma de se espalhar.', 0.4, 'O vírus precisa de um arquivo hospedeiro e de uma ação do usuário (abrir o executável) para se espalhar. O worm é autônomo: espalha-se sozinho pela rede, explorando vulnerabilidades, sem interação humana.', 'Nota cheia: diferença correta dos dois. Metade: só um descrito corretamente. Zero: trocados.'),
      (v_atividade, 6, 1, 'Explique o que é ransomware e por que pagar o resgate não é a solução.', 0.5, 'Ransomware é o malware que criptografa (sequestra) os arquivos e exige resgate para liberar, paralisando a operação. Pagar não garante a devolução dos dados, financia o crime e pode tornar a empresa alvo de novos ataques.', 'Nota cheia: definição + por que não pagar. Metade: só um dos dois. Zero: recomenda pagar.'),
      (v_atividade, 6, 2, 'Explique a regra de backup 3-2-1 e como ela teria evitado a perda dos arquivos nesse caso.', 0.5, '3 cópias (o original e mais duas), em 2 mídias diferentes, com 1 cópia fora do local (outro prédio ou nuvem). No caso, o único backup estava ligado ao servidor e foi criptografado junto; com uma cópia desconectada ou na nuvem, seria possível restaurar os arquivos sem pagar.', 'Nota cheia: explica 3-2-1 + aplica ao caso (cópia separada/externa). Metade: só um dos dois. Zero: regra errada.'),
      (v_atividade, 7, 1, 'Explique o problema de cada uma das quatro situações e crie um exemplo inventado de senha forte, dizendo as regras que ela segue.', 0.6, '"123456": sequência simples, quebrada na hora por força bruta. "valesul2026": nome da empresa + ano, fácil de adivinhar. "joao1985": dado pessoal e reutilizada em outros sistemas (se vazar um, vazam todos). Post-it no monitor: qualquer pessoa vê a senha. Exemplo inventado: "Doca7#Palete!Azul" (12 a 16 caracteres, maiúsculas, minúsculas, números e símbolos, sem dados pessoais, única para cada sistema, guardada num gerenciador de senhas).', 'Nota cheia: problema das quatro situações + exemplo forte com regras. Metade: duas ou três situações, ou exemplo sem regras. Zero: exemplo fraco e sem análise.'),
      (v_atividade, 7, 2, 'Explique o que é a autenticação em dois fatores (2FA) e cite os três tipos de fator.', 0.4, '2FA exige, além da senha, um segundo fator; mesmo que a senha seja descoberta, o invasor não entra. Fatores: algo que você sabe (senha), algo que você tem (token/app autenticador, chave USB) e algo que você é (biometria).', 'Nota cheia: conceito + três fatores. Metade: conceito com um ou dois fatores. Zero: sem relação.'),
      (v_atividade, 8, 1, 'Explique o que o HTTPS garante e por que o colega está errado.', 0.4, 'O HTTPS criptografa (TLS/SSL) a conexão entre o navegador e o servidor e valida a autenticidade do site, impedindo a interceptação dos dados no caminho. Mas não impede sites falsos/fraudulentos (golpistas também usam HTTPS) nem protege o restante do tráfego numa rede aberta.', 'Nota cheia: o que garante + o limite (não impede fraude). Metade: só um dos dois. Zero: concorda com o colega.'),
      (v_atividade, 8, 2, 'Descreva, em ordem, os passos do acesso remoto seguro, explicando a função da VPN.', 0.6, '1) Conectar-se a uma rede confiável protegida por senha (evitar o Wi-Fi aberto; usar o roteador do celular corporativo, se possível). 2) Iniciar e autenticar a VPN corporativa. 3) Inserir a credencial e validar o token 2FA. 4) Acessar a planilha no servidor. A VPN cria um túnel criptografado até a rede da empresa, protegendo o tráfego contra interceptação.', 'Nota cheia: passos na ordem + função da VPN. Metade: passos incompletos ou sem explicar a VPN. Zero: acessar direto pelo Wi-Fi aberto.'),
      (v_atividade, 9, 1, 'Explique o risco de ligar o pen drive desconhecido no computador da empresa e o que o conferente deve fazer com ele.', 0.5, 'O pen drive pode conter malware (vírus, trojan) que infecta o computador e captura credenciais ou dados da rede, como no caso do vazamento da folha de pagamento estudado. O conferente não deve conectá-lo: deve entregá-lo ao suporte de TI ou à segurança.', 'Nota cheia: risco de malware + entregar à TI sem conectar. Metade: só um dos dois. Zero: conectar para ver.'),
      (v_atividade, 9, 2, 'Explique o que deve ser feito agora com o celular perdido e quais proteções deveriam estar configuradas antes.', 0.5, 'Agora: avisar imediatamente a TI e o supervisor, bloquear/apagar remotamente o aparelho, trocar as senhas do e-mail e do WMS e encerrar as sessões abertas. Antes: senha forte/biometria e bloqueio automático de tela, criptografia do aparelho, rastreamento e bloqueio remoto configurados, só apps de lojas homologadas.', 'Nota cheia: ações imediatas + duas proteções prévias. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 10, 1, 'Para cada uma das cinco vulnerabilidades, proponha a medida corretiva.', 0.6, 'Post-it com senha: retirar, trocar a senha e usar gerenciador de senhas. Tela desbloqueada: bloquear sempre ao levantar (Windows + L) e configurar bloqueio automático. Pen drive pessoal desconhecido: retirar e entregar à TI; só usar dispositivos autorizados. Antivírus desatualizado: atualizar o antivírus e o sistema (atualização automática). Planilha só na Área de Trabalho: salvar na pasta/nuvem corporativa e fazer backup periódico (3-2-1).', 'Nota cheia: cinco medidas corretas. Metade: três ou quatro. Zero: duas ou menos.'),
      (v_atividade, 10, 2, 'Explique por que a segurança da informação depende das pessoas e não só da tecnologia, e a quem os incidentes devem ser reportados.', 0.4, 'A maioria dos incidentes começa com uma falha humana (clicar em phishing, senha fraca, tela aberta, pen drive desconhecido); a tecnologia não protege se as pessoas não seguirem os procedimentos, por isso a atenção e o treinamento são decisivos. Incidentes devem ser reportados imediatamente ao suporte de TI (e ao supervisor).', 'Nota cheia: papel das pessoas + reportar à TI imediatamente. Metade: só um dos dois. Zero: sem relação.');
end $$;
